import {button,icon,esc,phraseText,quotedText} from './ui.js';
import {lessonNumberWithVideo} from './video-lesson-state.js';
import {scenarioProgress,scenarioTitle} from './scenario-state.js';
export function renderReplyRepair(s,top,l,c){
 const p=scenarioProgress(s),x=c.items[p.index],jp=s.courseDirection==='ja-ko',ui=jp?'ja':'ko',lang=jp?'ko':'ja',label=(ko,ja)=>jp?ja:ko;
 const ratio=p.phase==='intro'?0:Math.round((p.index+(p.checked?1:0))/l.count*100),header=top(`${lessonNumberWithVideo(s,l.number[s.courseDirection])}. ${scenarioTitle(s,l)}`);
 const progress=`<div class="lesson-progress" role="progressbar" aria-label="${label('학습 진행률','学習の進み具合')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${ratio}"><span style="width:${ratio}%"></span></div>`;
 if(p.phase==='intro')return `${header}${progress}<main class="page scenario-page lesson-top" lang="${ui}"><h1>${esc(scenarioTitle(s,l))}</h1><p>${quotedText(c.scene)}</p>${button(label('답장 고치기','返事を直す'),'scenario-next')}</main>`;
 const line=(text,parts,part,meaning)=>`<div class="audio-text-row"><p lang="${lang}">${phraseText(text,parts||undefined)}</p>${button(icon('sound'),'scenario-audio','icon-button',`data-id="${part}" aria-label="${label('다시 듣기','もう一度聞く')}"`)}</div><details class="message-meaning"><summary>${label('뜻 보기','意味を見る')}</summary><p>${quotedText(meaning)}</p></details>`;
 const options=x.others.map((text,i)=>({text,feedback:x.othersFeedback[i]}));options.splice(p.index,0,{text:x.answer,parts:x.answerParts});
 return `${header}${progress}<main class="page scenario-page repair-page" lang="${ui}"><div class="scenario-count">${p.index+1} / ${l.count}</div><p>${quotedText(x.context)}</p><section class="repair-original"><h2>${label('처음 쓴 답장','最初の返事')}</h2>${line(x.text,x.phrases,'prompt',x.meaning)}</section>${p.checked?`<section class="repair-result" role="status"><h2>${label('고친 답장','言い換えた返事')}</h2>${line(x.answer,x.answerParts,'answer',x.answerMeaning)}<h3>${label('달라진 뜻','変わったニュアンス')}</h3><p class="scenario-feedback">${quotedText(x.hint)}</p></section>`:`<h2 class="repair-task">${quotedText(x.prompt)}</h2><div class="scenario-choices">${options.map((o,i)=>button(phraseText(o.text,o.parts||undefined),'scenario-select',`secondary${p.selected===i?' selected':''}`,`data-id="${i}" lang="${lang}" aria-pressed="${p.selected===i}"`)).join('')}</div>${p.retry?`<aside class="scenario-feedback" role="status"><p>${label('이 답장은 이런 뜻이에요.','この返事はこういう意味です。')}</p><p>${quotedText(options[p.selected]?.feedback||'')}</p></aside>`:''}`}<div class="button-pair">${button(label('이전','戻る'),'scenario-previous','secondary')}${p.checked?button(p.index===l.count-1?label('학습 마치기','学習を終える'):label('다음','次へ'),'scenario-next'):button(label('확인','確認'),'scenario-check','primary',p.selected===null?'disabled':'')}</div></main>`;
}
